def add_standard_lengths(apps, schema_editor):
    """Give every existing product the lengths and prices it had before (10"–32" in 2" steps)."""
    Product = apps.get_model("catalog", "Product")
    ProductLength = apps.get_model("catalog", "ProductLength")
    rows = []
    for product in Product.objects.all():
        step = {"bundle": 60, "closure": 70}.get(product.kind, 180)
        rows += [ProductLength(product=product, inches=10 + 2 * i, extra_price=i * step) for i in range(12)]
    ProductLength.objects.bulk_create(rows, ignore_conflicts=True)


